@push('scripts')
<script>
(function(){'use strict';const fields=[...document.querySelectorAll('.ra-denom')],corte=document.getElementById('ra-corte'),just=document.getElementById('ra-justificacion');const money=n=>'Q '+(Math.abs(n)/100).toLocaleString('es-GT',{minimumFractionDigits:2,maximumFractionDigits:2});function calcular(){let bil=0,mon=0;fields.forEach(el=>{const cantidad=Number(el.value);const cents=Number(el.dataset.centavos);const sub=Number.isSafeInteger(cantidad)&&cantidad>=0?cantidad*cents:0;el.closest('tr').querySelector('.ra-subtotal').textContent=money(sub);if(el.name.startsWith('billetes'))bil+=sub;else mon+=sub;});const total=bil+mon;const corteC=Math.round((Number(corte.value)||0)*100),dif=total-corteC;document.getElementById('ra-billetes').textContent=money(bil);document.getElementById('ra-monedas').textContent=money(mon);document.getElementById('ra-total').textContent=money(total);document.getElementById('ra-corte-resumen').textContent=money(corteC);document.getElementById('ra-diferencia').textContent=(dif<0?'-':'')+money(dif);document.getElementById('ra-resultado').textContent=dif>0?'Sobrante':dif<0?'Faltante':'Cuadrado';just.required=dif!==0;}fields.concat([corte]).forEach(el=>el.addEventListener('input',calcular));calcular();document.getElementById('ra-form').addEventListener('submit',function(e){if(!this.reportValidity())return;if(!confirm('¿Confirma que desea firmar definitivamente este arqueo?')){e.preventDefault();return;}document.getElementById('ra-enviar').disabled=true;});})();
</script>
